async function cancelBooking(id, btn) {
  if (cancelInFlight) return;
  cancelInFlight = true;
  if (btn) btn.disabled = true;
  try {
    var res = await fetch(CANCEL_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json; charset=utf-8', 'Accept': 'application/json' },
      body: JSON.stringify({ id: id })
    });

    var payload = null;
    try { payload = await res.json(); } catch (e) { payload = null; }

    if (res.status === 200) {
      showOk((payload && payload.message) ? payload.message : 'تم إلغاء الحجز بنجاح ✓');
    } else if (res.status === 404) {
      showError((payload && payload.error) ? payload.error : 'الحجز غير موجود أو أُلغي سابقًا.');
    } else if (res.status === 400) {
      showError((payload.error || 'طلب الإلغاء غير صالح.');
    } else {
      showError('حدث خطأ غير متوقع من الخادم (رمز ' + res.status + ').');
    }

    /* تحديث الجدول من الخادم بعد كل عملية إلغاء */
    await refresh();
  } catch (e) {
    showError('تعذر الاتصال بالخادم لإلغاء الحجز، أعد المحاولة.');
  } finally {
    cancelInFlight = false;
    if (btn) btn.disabled = false;
    if (btn && !btn.isConnected) btn = null;
  }
}

/* تفويض النقر: أي عنصر يحمل data-cancel داخل صف .booking يلغي حجزه دون نافذة تأكيد */
listEl.addEventListener('click', function (ev) {
  var btn = ev.target.closest('[data-cancel]');
  if (!btn || !listEl.contains(btn)) return;
  var row = btn.closest('.booking');
  if (!row) return;
  var id = Number(row.dataset.id);
  if (!Number.isInteger(id) || id <= 0) {
    showError('تعذر تحديد الحجز المطلوب إلغاؤه، حدّث القائمة ثم أعد المحاولة.');
    return;
  }
  cancelBooking(id, btn);
});

saveBtn.addEventListener('click', submit);
refreshBtn.addEventListener('click', refresh);

